document.addEventListener('DOMContentLoaded', () => {

    if ('scrollRestoration' in history) {
        history.scrollRestoration = 'manual';
    }

    let scrolled = 0;
    const totalScroll = 49
    function animateScroll() {
        if (scrolled < totalScroll) {
            window.scrollBy(0, 2);
            scrolled++;
            requestAnimationFrame(animateScroll);
        }
    }
    requestAnimationFrame(animateScroll);

    // Kept for Button Text labels
    const folderLabels = {
        default: 'figdesigns',
        alternate: 'jsconcepts'
    };
    
    let isAlternateMode = false;

    const hourHand = document.querySelector('.hour-hand');
    const minuteHand = document.querySelector('.minute-hand');
    const secondHand = document.querySelector('.second-hand');
    const millisecondHand = document.querySelector('.millisecond-hand');
    const body = document.body;
    const conceptMarkers = document.querySelectorAll('.concept-image');
    const toggleBtn = document.getElementById('asset-toggle');

    // NEW: Helper function to force Parcel to bundle these files
    function getAssetUrl(mode, i) {
        if (mode === 'figdesigns') {
            return new URL(`./figdesigns/${i}.png`, import.meta.url).href;
        } else {
            return new URL(`./jsconcepts/${i}.png`, import.meta.url).href;
        }
    }

    function updateImageSources(animate = false) {
        const currentMode = isAlternateMode ? 'jsconcepts' : 'figdesigns';

        const swapFiles = () => {
            conceptMarkers.forEach(img => {
                const i = parseInt(img.style.getPropertyValue('--i'));
                if (i) {
                    // UPDATED: Use the helper function instead of string path
                    img.src = getAssetUrl(currentMode, i);
                }
            });
        };

        const updateBtn = () => {
            if (toggleBtn) {
                // Logic updated to match your original "Switch to [Opposite]" behavior
                toggleBtn.textContent = isAlternateMode
                    ? `Switch to ${folderLabels.default}`
                    : `Switch to ${folderLabels.alternate}`;
            }
        };

        if (!animate) {
            swapFiles();
            updateBtn();
            return;
        }

        isTransitioning = true;

        conceptMarkers.forEach(img => img.classList.add('switching'));

        setTimeout(() => {
            swapFiles();
            updateBtn();

            requestAnimationFrame(() => {
                conceptMarkers.forEach(img => img.classList.remove('switching'));
                isTransitioning = false;
            });
        }, 400);
    }

    updateImageSources(false);

    if (toggleBtn) {
        toggleBtn.addEventListener('click', () => {
            isAlternateMode = !isAlternateMode;
            updateImageSources(true);
        });
    }


    function setClock() {
        const now = new Date();

        const milliseconds = now.getMilliseconds();
        const millisecondDegrees = (milliseconds / 1000) * 360;

        const seconds = now.getSeconds();
        const secondDegrees = ((seconds + milliseconds / 1000) / 60) * 360;

        const minutes = now.getMinutes();
        const minuteDegrees = ((minutes + seconds / 60) / 60) * 360;

        const hours = now.getHours();
        const hourDegrees = ((hours % 12 + minutes / 60) / 12) * 360;

        const markerIndex = Math.round(seconds / 5) === 0 || Math.round(seconds / 5) === 12 ? 12 : Math.round(seconds / 5);

        conceptMarkers.forEach(img => {
            const i = parseInt(img.style.getPropertyValue('--i'));
            if (i === markerIndex) {
                img.classList.add('active-marker');
            } else {
                img.classList.remove('active-marker');
            }
        });

        if (hours >= 12) {
            body.classList.add('pm-mode');
        } else {
            body.classList.remove('pm-mode');
        }

        millisecondHand.style.transform = `translateX(-50%) rotate(${millisecondDegrees}deg)`;
        secondHand.style.transform = `translateX(-50%) rotate(${secondDegrees}deg)`;
        minuteHand.style.transform = `translateX(-50%) rotate(${minuteDegrees}deg)`;
        hourHand.style.transform = `translateX(-50%) rotate(${hourDegrees}deg)`;

        requestAnimationFrame(setClock);
    }

    requestAnimationFrame(setClock);
});